local camera = game:GetService("Workspace").CurrentCamera;

local ballistic_handler = require(game:GetService("ReplicatedStorage"):FindFirstChild("Dependencies"):FindFirstChild("BallisticsHandler"), true);
local player = require(game:GetService("ReplicatedFirst"):FindFirstChild("PlayerModule"), true);

local character_handler = player.CharacterHandler;

function closest_target(range: number)
    local closest_part, closest_distance = nil, range;

    for _, player in (character_handler.Capsules) do
        local character = character_handler:GetCharacterFromCapsule(player);
        if (not character) then
            continue;
        end
        local head = character.Model.Human.Head;
        local screen_position, on_screen = camera:WorldToViewportPoint(head.Position);
        if (not on_screen) then
            continue;
        end
        local distance = (Vector2.new(screen_position.X, screen_position.Y) - camera.ViewportSize / 2).Magnitude;
        if (distance < closest_distance) then
            closest_part = head;
            closest_distance = distance;
        end
    end

    return closest_part;
end

local old; old = hookfunction(ballistic_handler.Fire, function(self, origin, direction, stats, replicated, ignore_list, seed1, seed2, server_time)
    local closest = closest_target(999);
    if (closest) then
        stats.Stats.Velocity = 99999;
        direction = (closest.Position - origin).Unit;
    end
    return old(self, origin, direction, stats, replicated, ignore_list, seed1, seed2, server_time);
end);
